rows=[]
for series,N,definitions in [('reproduction',18,R),('sprint_work',82,S)]:
 for n in range(1,N+1):
  found=list((ROOT/'experiments'/series).glob(f'{n:03}_*'));folder=found[0] if found else None
  ident=('R' if series=='reproduction' else 'sw')+f'{n:03}'
  if n in definitions:take,ceiling,lesson,placement=definitions[n]
  else:take=f'No assigned experiment folder or empirical result was located for sprint experiment {n:03}.';ceiling='no empirical claim';lesson='Preserve the numbering gap; do not invent a study or silently renumber later results.';placement='appendix'
  analysis=folder/'analysis.md' if folder else None; actual=analysis.exists() if analysis else False
  text=analysis.read_text() if actual else '';placeholder='<experiment name>' in text or (actual and len(text)<450 and 'Headline result' in text)
  readme=folder/'README.md' if folder else None; result_alt=folder/'RESULTS.md' if folder else None
  if not folder:status='unlocated_or_unassigned'
  elif placeholder or not actual:
   if series=='reproduction' and n==13:status='results_verified_analysis_missing'
   elif series=='reproduction' and n in [3,4,15]:status='planned_not_run'
   elif series=='sprint_work' and n==4:status='completed_results_in_RESULTS_md'
   elif series=='sprint_work' and n==74:status='forecast_frozen_scoring_pending'
   else:status='analysis_pending'
  elif series=='sprint_work' and n==73:status='analyzed_reporting_hold'
  elif series=='sprint_work' and n==63:status='completed_partly_verified'
  elif series=='sprint_work' and n==57:status='completed_mixed_verification'
  else:status='completed'
  sources=[str(x) for x in [analysis,readme,result_alt] if x and x.exists()]
  data=Path('/workspace/runs_executor')/f'sw{n:03}' if series=='sprint_work' else (folder/'src/results' if folder else None)
  if data and not data.exists(): data=None
  rows.append({'id':ident,'series':series,'number':n,'title':folder.name[4:].replace('_',' ') if folder else 'Number not assigned in located workspace','takeaway':take,'result_status':status,'narrative_recommendation':placement,'appendix_recommendation':'Include one row or slide; retain weak, inconclusive, gated and unrun branches.','evidence_ceiling':ceiling,'correction_or_lesson':lesson,'canonical_folder':str(folder) if folder else None,'canonical_analysis_path':str(analysis) if actual and not placeholder else str(result_alt) if result_alt and result_alt.exists() else None,'analysis_is_template':placeholder,'source_paths':sources,'plot_data_root':str(data) if data else None,'source_analysis_sha256':hashlib.sha256(text.encode()).hexdigest() if actual else None,'source_read_scope':'Existing full reads and targeted headline/verdict/correction reads; no fresh experiment or blind recomputation in this registry task.','snapshot_utc':NOW})
assert len(rows)==100 and len(set(r['id'] for r in rows))==100
for r in rows:assert r['takeaway'].endswith('.')
obj={'created_utc':NOW,'scope':'Complete numbered coverage: reproduction001–018 and sprint001–082, including missing numbers and placeholder analyses.','refresh_note':'Snapshot, not a live run-status service. Parent refreshes late analyses. Never infer result status from filename presence alone.','entries':rows,'counts_by_status':dict(collections.Counter(r['result_status'] for r in rows))}
OUT.mkdir(parents=True,exist_ok=True);(OUT/(DAY+'_appendix_coverage.json')).write_text(json.dumps(obj,indent=2,ensure_ascii=False)+'\n')
lines=['# Complete numbered experiment coverage for the appendix','',NOW+' (from `date -u`).','',obj['scope'],'','Every entry has a full-sentence takeaway, evidence ceiling and correction. Main-deck recommendations are editorial suggestions; all entries remain covered in the appendix. Pending slots are not findings.','']
for series in ['reproduction','sprint_work']:
 lines += ['## '+series,'','| Experiment | Takeaway | Status / placement | Evidence ceiling | Correction or lesson | Canonical record |','|---|---|---|---|---|---|']
 for r in rows:
  if r['series']!=series:continue
  path=r['canonical_analysis_path'] or r['canonical_folder'] or 'No folder located'
  lines.append('| '+ ' | '.join([r['id'],r['takeaway'],r['result_status']+' / '+r['narrative_recommendation'],r['evidence_ceiling'],r['correction_or_lesson'],'`'+path+'`'])+' |')
lines+=['','## Scope and counting notes','','- The four numbering gaps in the sprint series are retained as unlocated/unassigned entries; they are not experiments with negative outcomes.','- Reproduction thirteen has verified result tables despite a template analysis; sprint four uses RESULTS.md.','- Reproduction three and four are planned; reproduction fifteen is on hold; reproduction seven has no located folder.','- Sprint eighty-two is the renumbered register-mechanism replication; its legacy keys are not the shared-protocol battery.','- Unnumbered explorations (X0–X9, extract1028 and sae1029) are covered in the separate reproduction inventory and should receive their own appendix group.','- The JSON includes source hashes so a later landed analysis can be detected without mistaking this snapshot for final status.']
(OUT/(DAY+'_appendix_coverage.md')).write_text('\n'.join(lines)+'\n')
print('WROTE100 coverage entries',obj['counts_by_status'])
